comments.body:
I wonder if it would be possible to check stdin if data would be available before `io.ReadAll(os.Stdin)`, sth like:

```
func stdinReady() error {
	stat, err := os.Stdin.Stat()
	if err != nil {
		return fmt.Errorf("failed to stat stdin: %w", err)
	}

	if stat.Mode().IsRegular() {  // regular file, return immediat.
		return nil
	}

	pollFds := []unix.PollFd{{
		Fd:     int32(os.Stdin.Fd()),
		Events: unix.POLLIN | unix.POLLPRI | unix.POLLERR | unix.POLLNVAL | unix.POLLHUP,
	}}

again:
	n, err := unix.Poll(pollFds, 0)  // check if we have data
	if err != nil {
		if err == unix.EAGAIN || err == unix.EINTR {
			goto again
		}

		return fmt.Errorf("failed to poll stdin: %w", err)
	}

	if n == 0 { // no data --> don't try to read from stdin as this would hang
		return errWaitingForStdinData
	}

	revents := pollFds[0].Revents
	if revents&(unix.POLLERR|unix.POLLNVAL) != 0 {
		return fmt.Errorf("failed to poll stdin: revents=%#x", revents)
	}

	if revents&(unix.POLLIN|unix.POLLPRI|unix.POLLHUP) == 0 { // also no data
		return errWaitingForStdinData
	}

	return nil // fall through, ok to read
}
```
